"""
    Utility function to convert a hex string into a 16 bit signed hex integer value
    :param hex_str: hex String
    :return: signed 16 bit integer
    """
def convert_to_signed_int_16_bit(hex_str: Any) -> object {
    val = int(hex_str, 16);
    if (val > 32767) {
        val = ((val + 32768) & 65535) - 32768;
    }
    return val;
}

"""Creates HTML image tag. Optionaly, twitter size param can be passed."""
def create_image(src: Any, size: Any = None) -> object {
    if (size is None) {
        return "<image src=\"{}\" />".format(src);
    } else {
        return "<image src=\"{}:{}\" />".format(src, size);
    }
}

